function showResults() {
  let dropdownContent = document.getElementById("dropdownContent");
  dropdownContent.innerHTML = ''; // Clear previous results
  locations.slice(0, 5).forEach(function(location) {
    dropdownContent.innerHTML += '<a href="' + location.slug + '" class="search-result-item w-inline-block"><div class="search-result-item">' + location.name + '</div><div class="w-embed"><svg class="g__result-icon" xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"></line><polyline points="7 7 17 7 17 17"></polyline></svg></div></a>';
  });
  dropdownContent.style.display = "block";
}

function filterResults() {
  let input = document.getElementById("Standort");
  let filter = input.value.toUpperCase();
  let dropdownContent = document.getElementById("dropdownContent");
  dropdownContent.innerHTML = ''; // Clear previous results
  if (filter.length === 0) {
    dropdownContent.style.display = "none";
    return;
  }
  let filteredLocations = locations.filter(location => location.name.toUpperCase().includes(filter)).slice(0, 5);
  filteredLocations.forEach(function(location) {
    dropdownContent.innerHTML += '<a href="' + location.slug + '" class="search-result-item w-inline-block"><div class="search-result-item">' + location.name + '</div><div class="w-embed"><svg class="g__result-icon" xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"></line><polyline points="7 7 17 7 17 17"></polyline></svg></div></a>';
  });
  if (filteredLocations.length > 0) {
    dropdownContent.style.display = "block";
  } else {
    dropdownContent.style.display = "none";
  }
}

document.addEventListener('click', function(event) {
  let dropdown = document.getElementsByClassName('dropdown')[0];
  if (!dropdown.contains(event.target)) {
    document.getElementById("dropdownContent").style.display = "none";
  }
});
